def nodes(x,t):
 if isinstance(x,dict):
  if x.get('t')==t:yield x
  for v in x.values():yield from nodes(v,t)
 elif isinstance(x,list):
  for v in x:yield from nodes(v,t)
def stream(x):
 if isinstance(x,list):return ''.join(stream(v) for v in x)
 if not isinstance(x,dict):return ''
 t=x.get('t');c=x.get('c')
 if t=='Str':return c
 if t in ['Space','SoftBreak','LineBreak']:return ' '
 if t=='Math':
  d='$$' if c[0]['t']=='DisplayMath' else '$';return d+c[1]+d
 if t in ['Link','Span']:return stream(c[1])
 if t in ['RawInline','RawBlock','Image']:return ''
 if t in ['Para','Plain']:return stream(c)+'\n'
 return stream(c)
